import cocotb
from cocotb.triggers import Timer
from riscv_assembler.convert import AssemblyConverter


def assemble_rv32im(source: str) -> int:
    """Assemble one RV32IM instruction and return its 32-bit word."""
    result = AssemblyConverter().convert(source)
    if isinstance(result, (list, tuple)):
        result = result[0]

    if isinstance(result, int):
        return result & 0xFFFFFFFF

    encoded = str(result).strip()
    if len(encoded) == 32 and set(encoded) <= {"0", "1"}:
        return int(encoded, 2)
    if encoded.startswith("0b"):
        return int(encoded, 2)
    if encoded.startswith("0x"):
        return int(encoded, 16)
    return int(encoded, 16)


@cocotb.test()
async def test_positive_addi_has_zero_i_immediate_upper_bits(dut):
    instruction = assemble_rv32im("addi x1, x0, 7")
    dut.instr.value = instruction
    await Timer(1, unit="ns")

    observed = int(dut.imm_i.value)
    assert observed & 0xFFFFF000 == 0x00000000, (
        f"imm_i upper bits expected 0x00000000, "
        f"observed 0x{observed & 0xFFFFF000:08X}"
    )
